dir:

































  &DefaultButton;




function dir$dmquocgia(p){
  this.constructor(p);
}
dir$dmquocgia.prototype = new DirEvent();
dir$dmquocgia.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmquocgia.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmquocgiaDisabledMasterField(p, g);

}

function dir$dmquocgiaDisabledMasterField(p, g){

  if(p.valForm('ma_qg').trim() != '')
  {
    p.setDisabled('ma_qg', true);
  }
  else
  {
    p.setDisabled('ma_qg', false);
  }
}






	.control-label.ma_qg, .control-label.ten_qg
	{	
		//font-weight:bold;	
		color: #499b98;;
	}








declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã quốc gia đã tồn tại.' else N'Country code already exists.' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã quốc gia đã tồn tại.' else N'Country code already exists.' end
